// A: ack first, work after -> at-most-once
await broker.ack(msg);
await sendEmail(msg.body);   // crash before this line: message LOST

// B: work first, ack after -> at-least-once
await sendEmail(msg.body);
await broker.ack(msg);       // crash before this line: message REPEATED

BEGIN;
INSERT INTO processed_messages (message_id) VALUES ('m-81'); -- PRIMARY KEY
UPDATE accounts SET balance = balance - 10 WHERE id = 7;
COMMIT;
-- A second delivery makes the INSERT fail with a duplicate key:
-- the whole transaction is stopped and the message is skipped.

const queue = new Queue("payments", { connection });
await queue.add("charge", { orderId: 7 }, {
  attempts: 3,                                   // runs at most 3 times
  backoff: { type: "exponential", delay: 1000 }, // 1 s, then 2 s
  delay: 60_000,                                 // not before 60 s
});

new Worker("payments", async (job) => {
  await gateway.charge(job.data);
}, { connection, concurrency: 5 });

const { Messages } = await sqs.send(new ReceiveMessageCommand({
  QueueUrl,
  WaitTimeSeconds: 20,        // long polling
}));
for (const m of Messages ?? []) {
  await sendEmail(m.Body);
  await sqs.send(new DeleteMessageCommand({
    QueueUrl, ReceiptHandle: m.ReceiptHandle,   // the ack
  }));
}

for (const row of unsentRows) {
  await broker.publish(row.event);                      // 1
  // <- a crash here means: published, but not marked
  await db.query("UPDATE outbox SET sent = true WHERE id = $1", [row.id]); // 2
}
